// Package relayproof implements cross-chain message verification.
package relayproof

import (
	"errors"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"sync"
	"syscall"
)

// maxProcessTime is the largest legal processing time: non-negative int64
// Unix milliseconds, up to the int64 ceiling.
const maxProcessTime = math.MaxInt64

// Durable queue statuses. Pending and waiting are live; the rest are terminal.
const (
	StatusPending    = "pending"        // accepted, not processed for the first time yet
	StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
	StatusSuccess    = "success"        // recorded locally and nonce consumed
	StatusReplay     = "replay"         // nonce combination already consumed by another message
	StatusExpired    = "expired"        // absolute expiry reached before delivery
	StatusUnknownSrc = "unknown-source" // source chain was never registered
)

// Common errors. Callers can compare with errors.Is.
var (
	// ErrConflict is returned when an id is reused with different message content.
	ErrConflict = errors.New("message id conflict: existing record has different content")
	// ErrHeaderConflict is returned when a trusted header is submitted at the
	// height of the accepted highest trusted header with a different root. The
	// accepted trusted header is kept and the queue remains usable.
	ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
	// ErrTerminal is returned when re-submitting a terminal id or attempting to
	// reactivate it.
	ErrTerminal = errors.New("message is terminal and cannot be reactivated")
	// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
	ErrInvalidArg = errors.New("invalid argument")
	// ErrLocked is returned when another process holds the state directory open.
	ErrLocked = errors.New("state directory is locked by another process")
	// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
	ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
	// ErrStorage is returned after a storage failure; the queue must be reopened.
	ErrStorage = errors.New("storage failure; queue must be reopened")
)

// Envelope is a submitted message together with its absolute expiry time.
type Envelope struct {
	Message Message
	// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
	ExpiresAt int64
}

// Record is the full persisted state of one submitted message.
type Record struct {
	Msg        Envelope
	Status     string
	Reason     string
	Seq        int64 // submission order, zero-based
	Attempts   int   // number of processing attempts
	NextRetry  int64 // 0 when not yet processed, or terminal
	LastProcAt int64 // processing time of the most recent attempt
}

// Query is the user-visible view of a Record.
type Query struct {
	ID        string
	From      string
	To        string
	Nonce     uint64
	Payload   string
	ProofAt   int64
	ExpiresAt int64
	Status    string
	Reason    string
	NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
	Attempts  int
}

// AdvanceReport is the outcome of one Advance call.
type AdvanceReport struct {
	Now     int64
	Results []Result
}

// Result describes what happened to one message during an Advance.
type Result struct {
	ID     string `json:"id"`
	Status string `json:"status"`
	Reason string `json:"reason"`
}

// headerState records the headers seen for one chain: the latest header
// written (any trust level) and the highest trusted header accepted. Proof
// coverage is determined solely by the highest trusted header — a later
// untrusted header, even at a greater height, can never lower or invalidate
// it. The zero value is a chain with no recorded headers.
type headerState struct {
	latest  Header
	trusted *Header
}

// Queue is a durable local outbox backed by a state directory. A single
// Queue owns the directory for writes; other processes attempting to Open the
// same directory fail with ErrLocked. It is safe for concurrent use by
// multiple goroutines, and a success record plus its nonce consumption commit
// as one durable unit.
type Queue struct {
	mu sync.Mutex

	store  *store
	flock  *os.File
	broken bool // a storage write failed; all further mutations fail

	now      int64                   // last advanced Unix-ms time, 0 = never advanced
	sources  map[string]bool         // registered source chains
	headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
	records  map[string]*Record      // by message id
	order    []string                // non-terminal messages, submission order
	consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
	nextSeq  int64
}

// Open opens (creating if needed) a persistent queue backed by stateDir. It
// takes an exclusive process lock on the directory and refuses to start when
// the on-disk state is corrupt or in an unsupported format, never clearing it.
func Open(stateDir string) (*Queue, error) {
	if stateDir == "" {
		return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
	}
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		return nil, fmt.Errorf("create state directory: %w", err)
	}
	abs, err := filepath.Abs(stateDir)
	if err != nil {
		return nil, fmt.Errorf("resolve state directory: %w", err)
	}

	lockPath := filepath.Join(abs, "lock")
	lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file: %w", err)
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return nil, fmt.Errorf("%w: %v", ErrLocked, err)
	}

	st, state, err := openStore(abs)
	if err != nil {
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}

	q := &Queue{
		store:    st,
		flock:    lock,
		sources:  state.sources,
		headers:  state.headers,
		records:  state.records,
		consumed: state.consumed,
		now:      state.now,
		nextSeq:  state.nextSeq,
	}
	q.order = q.reconstructOrder()
	st.snap = q.snapshot
	return q, nil
}

// reconstructOrder returns non-terminal record ids in submission (seq) order.
func (q *Queue) reconstructOrder() []string {
	seqs := make([]int64, 0, len(q.records))
	live := map[int64]string{}
	for id, rec := range q.records {
		if isTerminal(rec.Status) {
			continue
		}
		seqs = append(seqs, rec.Seq)
		live[rec.Seq] = id
	}
	sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
	order := make([]string, 0, len(seqs))
	for _, seq := range seqs {
		order = append(order, live[seq])
	}
	return order
}

// snapshot returns a detached copy of live state for log compaction. Callers
// must hold mu.
func (q *Queue) snapshot() *loadedState {
	s := &loadedState{
		sources:  map[string]bool{},
		headers:  map[string]*headerState{},
		records:  map[string]*Record{},
		consumed: map[consumeToken]string{},
		now:      q.now,
		nextSeq:  q.nextSeq,
	}
	for c := range q.sources {
		s.sources[c] = true
	}
	for c, h := range q.headers {
		cp := &headerState{latest: h.latest}
		if h.trusted != nil {
			t := *h.trusted
			cp.trusted = &t
		}
		s.headers[c] = cp
	}
	for id, rec := range q.records {
		cp := *rec
		s.records[id] = &cp
	}
	for k, v := range q.consumed {
		s.consumed[k] = v
	}
	return s
}

// Close flushes, releases the directory lock and closes the queue.
func (q *Queue) Close() error {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.flock == nil {
		return nil
	}
	var err error
	if !q.broken {
		err = q.store.close()
	} else {
		q.store.forceClose()
	}
	syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
	q.flock.Close()
	q.flock = nil
	return err
}

// fail locks in a storage failure: the log tail may be partially written, so
// no further appends are allowed in this process (another append would turn a
// truncatable torn tail into unrecoverable corruption).
func (q *Queue) fail(op string, err error) error {
	q.broken = true
	return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
}

func (q *Queue) checkWritable() error {
	if q.flock == nil {
		return fmt.Errorf("%w: queue is closed", ErrStorage)
	}
	if q.broken {
		return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
	}
	return nil
}

// RegisterSource records that messages may originate from chain. Idempotent.
func (q *Queue) RegisterSource(chain string) error {
	if chain == "" {
		return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return err
	}
	if q.sources[chain] {
		return nil
	}
	if err := q.store.appendRegisterSource(chain); err != nil {
		return q.fail("register source", err)
	}
	q.sources[chain] = true
	return q.maybeCompact()
}

// UpsertHeader records a header for a chain. The latest header is always
// recorded, but proof coverage is determined solely by the highest trusted
// header accepted for the chain:
//
//   - the first trusted header establishes coverage;
//   - a higher trusted header advances it;
//   - a lower trusted header, or an untrusted header of any height, is
//     recorded but can never lower or invalidate established coverage;
//   - a trusted header at the current highest trusted height with the same
//     root is an idempotent no-op;
//   - a trusted header at that height with a different root is an
//     ErrHeaderConflict: the accepted trusted header is kept and the queue
//     remains usable.
//
// Header updates never bypass retry scheduling, never process messages, and
// never reactivate terminal messages.
func (q *Queue) UpsertHeader(h Header) error {
	if h.Chain == "" {
		return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
	}
	if h.Height < 0 {
		return fmt.Errorf("%w: negative header height", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return err
	}
	hs := q.headers[h.Chain]
	if hs == nil {
		hs = &headerState{}
		q.headers[h.Chain] = hs
	}
	if h.Trusted && hs.trusted != nil &&
		h.Height == hs.trusted.Height && h.Root != hs.trusted.Root {
		return fmt.Errorf("%w: chain %q height %d: submitted root %q conflicts with accepted root %q",
			ErrHeaderConflict, h.Chain, h.Height, h.Root, hs.trusted.Root)
	}
	if err := q.store.appendHeader(h); err != nil {
		return q.fail("upsert header", err)
	}
	hs.latest = h
	if h.Trusted && (hs.trusted == nil || h.Height > hs.trusted.Height) {
		t := h
		hs.trusted = &t
	}
	return q.maybeCompact()
}

// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
// means never expire). Re-submitting the same id with identical content
// returns the existing record without adding a queue entry; the same id with
// different content returns ErrConflict and leaves the original untouched;
// re-submitting a terminal id returns ErrTerminal. Success is reported only
// after the submission is durably persisted.
func (q *Queue) Submit(env Envelope) (*Record, error) {
	m := env.Message
	if m.ID == "" {
		return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
	}
	if m.From == "" || m.To == "" {
		return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
	}
	if m.ProofAt < 0 {
		return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
	}
	if env.ExpiresAt < 0 {
		return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return nil, err
	}

	if existing, ok := q.records[m.ID]; ok {
		if isTerminal(existing.Status) {
			return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
		}
		if sameEnvelope(existing.Msg, env) {
			out := *existing
			return &out, nil
		}
		return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
	}

	rec := &Record{
		Msg:    env,
		Status: StatusPending,
		Reason: "awaiting first processing",
		Seq:    q.nextSeq,
	}
	if err := q.store.appendSubmit(rec); err != nil {
		return nil, q.fail("submit", err)
	}
	q.records[m.ID] = rec
	q.order = append(q.order, m.ID)
	q.nextSeq++
	if err := q.maybeCompact(); err != nil {
		return nil, err
	}
	out := *rec
	return &out, nil
}

// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
// be advanced repeatedly; going backwards is rejected and changes nothing.
//
// Each advance, in submission order:
//  1. due messages (new messages are due on the next advance; others when now
//     has reached their next retry time) are evaluated for replay and expiry,
//     replay winning on a tie and now == ExpiresAt counting as expired, then
//     for source registration and trusted-header coverage, and finally
//     delivered;
//  2. afterwards every remaining non-terminal message, regardless of its
//     retry schedule, is re-checked for replay and expiry at the new time.
//
// Unregistered sources are permanently rejected as unknown-source; registered
// sources without a trusted header covering the proof height stay waiting and
// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
// doubling to a 60-second cap, measured from the actual processing time;
// jumping over several intervals still costs one attempt.
//
// The retry instant saturates at the int64 ceiling: a waiting message whose
// computed retry would overflow is scheduled for math.MaxInt64 instead, never
// a negative, zero or earlier-than-processing instant. Once such a message has
// been processed at the ceiling, every later advance is at the same instant,
// so it is never due again and keeps its waiting status, reason, attempt
// count and ceiling retry time; it is neither reprocessed nor reported again
// as a waiting result. Replay and expiry checks, which run independently of
// the retry schedule, still apply to it, and a header update alone never
// delivers it.
func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
	if nowMs < 0 {
		return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return nil, err
	}
	if q.now != 0 && nowMs < q.now {
		return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
	}

	report := &AdvanceReport{Now: nowMs}

	// Phase 1: due messages, first-submission order.
	for _, id := range append([]string(nil), q.order...) {
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		due := rec.Attempts == 0 || retryDue(rec, nowMs)
		if !due {
			continue
		}
		if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
			return nil, err
		} else if done {
			report.Results = append(report.Results, r)
			continue
		}
		r, err := q.processDue(rec, nowMs)
		if err != nil {
			return nil, err
		}
		report.Results = append(report.Results, r)
	}

	// Phase 2: replay/expiry hold for every non-terminal message at the new
	// time, even while its retry backoff is still running.
	for _, id := range append([]string(nil), q.order...) {
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
			return nil, err
		} else if done {
			report.Results = append(report.Results, r)
		}
	}

	if err := q.store.appendAdvance(nowMs); err != nil {
		return nil, q.fail("advance", err)
	}
	q.now = nowMs
	if err := q.maybeCompact(); err != nil {
		return nil, err
	}
	return report, nil
}

// maybeCompact rewrites the WAL as a snapshot once it grows past the
// threshold. Live state already reflects every acknowledged append, so the
// snapshot cannot lose records. A compaction failure is a storage failure:
// the queue is marked broken and must be reopened.
func (q *Queue) maybeCompact() error {
	if !q.store.needsCompaction() {
		return nil
	}
	if err := q.store.compact(q.snapshot()); err != nil {
		return q.fail("compact log", err)
	}
	return nil
}

// checkReplayExpiry terminalizes rec when its nonce was consumed by another
// message or its absolute expiry has been reached. Replay wins when both
// hold. The bool reports whether the message was terminalized.
func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
	id := rec.Msg.Message.ID
	token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
	if winner, taken := q.consumed[token]; taken && winner != id {
		reason := "nonce combination already consumed by message " + winner
		if err := q.terminalize(rec, now, StatusReplay, reason); err != nil {
			return Result{}, false, err
		}
		return Result{ID: id, Status: StatusReplay, Reason: reason}, true, nil
	}
	if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
		reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
		if err := q.terminalize(rec, now, StatusExpired, reason); err != nil {
			return Result{}, false, err
		}
		return Result{ID: id, Status: StatusExpired, Reason: reason}, true, nil
	}
	return Result{}, false, nil
}

// processDue classifies a due message against source registration and header
// trust, or delivers it.
func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
	id := rec.Msg.Message.ID
	if !q.sources[rec.Msg.Message.From] {
		reason := "unknown source chain " + rec.Msg.Message.From
		if err := q.terminalize(rec, now, StatusUnknownSrc, reason); err != nil {
			return Result{}, err
		}
		return Result{ID: id, Status: StatusUnknownSrc, Reason: reason}, nil
	}
	hs := q.headers[rec.Msg.Message.From]
	if hs == nil || hs.trusted == nil || hs.trusted.Height < rec.Msg.Message.ProofAt {
		cur := int64(0)
		if hs != nil && hs.trusted != nil {
			cur = hs.trusted.Height
		}
		reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", rec.Msg.Message.ProofAt, cur)
		if err := q.markWaiting(rec, now, reason); err != nil {
			return Result{}, err
		}
		return Result{ID: id, Status: StatusWaiting, Reason: reason}, nil
	}

	// Deliver: success record and nonce consumption are one log entry. The
	// coverage height is the highest trusted header actually accepted — never
	// a higher untrusted header.
	token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
	reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
	if err := q.store.appendResult(now, rec, StatusSuccess, reason, rec.Attempts+1, &token, id); err != nil {
		return Result{}, q.fail("deliver", err)
	}
	rec.Attempts++
	rec.LastProcAt = now
	rec.Status = StatusSuccess
	rec.Reason = reason
	rec.NextRetry = 0
	q.consumed[token] = id
	q.removeFromOrder(id)
	return Result{ID: id, Status: StatusSuccess, Reason: reason}, nil
}

func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
	if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, nil, ""); err != nil {
		return q.fail("terminalize", err)
	}
	rec.Attempts++
	rec.LastProcAt = now
	rec.Status = status
	rec.Reason = reason
	rec.NextRetry = 0
	q.removeFromOrder(rec.Msg.Message.ID)
	return nil
}

func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
	attempt := rec.Attempts + 1
	nextRetry := nextRetryAt(now, attempt)
	if err := q.store.appendWaiting(now, rec, reason, attempt, nextRetry); err != nil {
		return q.fail("schedule retry", err)
	}
	rec.Attempts = attempt
	rec.LastProcAt = now
	rec.Status = StatusWaiting
	rec.Reason = reason
	rec.NextRetry = nextRetry
	return nil
}

// retryDue reports whether a waiting record's next retry is reached at now.
// Backoff delays are always positive, so every representable retry lies
// strictly after the processing time that scheduled it; a waiting message is
// therefore evaluated at most once per distinct processing time. The only
// instant where the retry cannot lie later is the int64 ceiling: there the
// schedule saturates to the ceiling itself. Once the message was processed at
// the ceiling, every legal advance is at the same instant, so the retry can
// never be reached "later" — treating equal time as due would reprocess the
// message on every advance, inflate attempts and re-report waiting forever.
func retryDue(rec *Record, now int64) bool {
	if now < rec.NextRetry {
		return false
	}
	return now != rec.LastProcAt
}

func (q *Queue) removeFromOrder(id string) {
	for i, cand := range q.order {
		if cand == id {
			q.order = append(q.order[:i], q.order[i+1:]...)
			return
		}
	}
}

// nextRetryAt returns the retry instant after the attempt-th processing at
// now: now plus the backoff delay, saturated at math.MaxInt64. Saturation
// keeps the scheduled retry non-negative, never zero (when processed at a
// positive time) and never earlier than the processing time; when the true
// retry overflows int64 the ceiling is the nearest representable instant.
func nextRetryAt(now int64, attempt int) int64 {
	delay := nextRetryDelay(attempt)
	if now > maxProcessTime-delay {
		return maxProcessTime // now+delay would overflow; delay is at most 60000
	}
	return now + delay
}

// nextRetryDelay is the backoff after the attempt-th processing (1-based):
// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
func nextRetryDelay(attempt int) int64 {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 6 {
		return 60_000
	}
	return int64(1) << (attempt - 1) * 1000
}

func isTerminal(status string) bool {
	switch status {
	case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

func sameEnvelope(a, b Envelope) bool {
	return a.ExpiresAt == b.ExpiresAt &&
		a.Message.ID == b.Message.ID &&
		a.Message.From == b.Message.From &&
		a.Message.To == b.Message.To &&
		a.Message.Nonce == b.Message.Nonce &&
		a.Message.Payload == b.Message.Payload &&
		a.Message.ProofAt == b.Message.ProofAt
}

// Query returns the current state of a message.
func (q *Queue) Query(id string) (Query, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	rec, ok := q.records[id]
	if !ok {
		return Query{}, false
	}
	return toQuery(rec), true
}

// Queries returns all records in first-submission order.
func (q *Queue) Queries() []Query {
	q.mu.Lock()
	defer q.mu.Unlock()
	out := make([]Query, 0, len(q.records))
	for _, rec := range q.records {
		out = append(out, toQuery(rec))
	}
	sort.Slice(out, func(i, j int) bool {
		return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
	})
	return out
}

// Now returns the last advanced processing time, or 0 if never advanced.
func (q *Queue) Now() int64 {
	q.mu.Lock()
	defer q.mu.Unlock()
	return q.now
}

func toQuery(rec *Record) Query {
	return Query{
		ID:        rec.Msg.Message.ID,
		From:      rec.Msg.Message.From,
		To:        rec.Msg.Message.To,
		Nonce:     rec.Msg.Message.Nonce,
		Payload:   rec.Msg.Message.Payload,
		ProofAt:   rec.Msg.Message.ProofAt,
		ExpiresAt: rec.Msg.ExpiresAt,
		Status:    rec.Status,
		Reason:    rec.Reason,
		NextRetry: rec.NextRetry,
		Attempts:  rec.Attempts,
	}
}

package relayproof

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"hash/crc32"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
)

// On-disk format (queue.log):
//
//	magic   = "RELAYPROOF-QUEUE-V1\n"
//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
//
// The log is an append-only write-ahead log. Every mutating operation is
// persisted as one framed, checksummed record and fsynced before it is
// acknowledged; a success record frames the local success entry and the nonce
// consumption together, so the two can never take effect separately.
//
// A success (result or compacted state) names the consumed triple in three
// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
// U+0000 — so the triple is never flattened into one delimiter-joined string,
// which would let distinct routing paths share one consumption identity.
//
// Crash recovery: a frame missing bytes at end of file, or a final frame with
// a bad checksum, is the torn tail of a write that was never acknowledged and
// is truncated. That recovery is only available once the log's leading
// version record has itself been read whole and verified: the magic alone
// never establishes a usable version, so a log whose very first record is
// partial (only some length bytes, or the length without the body and CRC),
// complete but checksum-bad, not a version record, or names an unsupported
// version is rejected wholesale with ErrCorrupt and left byte-for-byte
// untouched — it can never be truncated down to an empty-looking log that a
// later append would turn into a headerless one. Bad checksums or framing
// anywhere before the end, a foreign header, or an unsupported version
// likewise reject the directory with ErrCorrupt; state is never silently
// cleared.
//
// Logs written by older builds recorded the consumption as one NUL-joined
// consumeKey string. Such success entries are still accepted on replay: the
// key is validated against the record's own (from,to,nonce) and consumeBy,
// and only the record's own triple is marked consumed. A legacy key that does
// not match the record it is attached to — a genuinely inconsistent old
// record — rejects the whole directory with ErrCorrupt instead of silently
// accepting or "repairing" the bad entry.

const (
	logName          = "queue.log"
	logMagic         = "RELAYPROOF-QUEUE-V1\n"
	compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
	compactFileMode  = 0o600
	frameHeaderSize  = 4
	frameCRCsSize    = 4
)

var crcTable = crc32.MakeTable(crc32.IEEE)

// JSON log entry kinds.
const (
	kindVersion = "version"
	kindSource  = "source"
	kindHeader  = "header"
	kindSubmit  = "submit"
	kindResult  = "result"
	kindState   = "state" // compacted snapshot: full status after >=1 attempts
	kindAdvance = "advance"
	currentLogV = 1
)

type logEntry struct {
	T string `json:"t"`
	V int    `json:"v,omitempty"`

	Chain   string `json:"chain,omitempty"`
	Height  int64  `json:"height,omitempty"`
	Root    string `json:"root,omitempty"`
	Trusted bool   `json:"trusted,omitempty"`

	Seq       int64  `json:"seq,omitempty"`
	ID        string `json:"id,omitempty"`
	From      string `json:"from,omitempty"`
	To        string `json:"to,omitempty"`
	Nonce     uint64 `json:"nonce,omitempty"`
	Payload   string `json:"payload,omitempty"`
	ProofAt   int64  `json:"proofAt,omitempty"`
	ExpiresAt int64  `json:"expiresAt,omitempty"`

	Now       int64  `json:"now,omitempty"`
	Status    string `json:"status,omitempty"`
	Reason    string `json:"reason,omitempty"`
	Attempts  int    `json:"attempts,omitempty"`
	NextRetry int64  `json:"nextRetry,omitempty"`

	// Consumed triple of a success entry, stored as three independent values
	// so routing paths that share a flattened key stay distinct. consumeBy is
	// the id of the successful message.
	ConsumeFrom  string `json:"consumeFrom,omitempty"`
	ConsumeTo    string `json:"consumeTo,omitempty"`
	ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
	ConsumeBy    string `json:"consumeBy,omitempty"`

	// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
	// is accepted only while replaying logs written by older builds and is
	// never written anymore.
	ConsumeKey string `json:"consumeKey,omitempty"`
}

// legacyNonceKey reproduces the consumption string used by older builds:
// from NUL to NUL nonce. It exists solely to validate records in pre-existing
// state directories; new state always uses consumeToken triples.
func legacyNonceKey(from, to string, nonce uint64) string {
	return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
}

type store struct {
	dir  string
	f    *os.File
	size int64
	// snap, when set, supplies a live-state snapshot for log compaction.
	snap func() *loadedState
	// injectErr is a test hook forcing append to fail after opening the file.
	injectErr error
}

// loadedState is the fully replayed (or live) queue state.
type loadedState struct {
	sources  map[string]bool
	headers  map[string]*headerState
	records  map[string]*Record
	consumed map[consumeToken]string
	nextSeq  int64
	now      int64
}

func openStore(dir string) (*store, *loadedState, error) {
	path := filepath.Join(dir, logName)

	if _, err := os.Stat(path); err != nil {
		if !os.IsNotExist(err) {
			return nil, nil, fmt.Errorf("stat %s: %w", logName, err)
		}
		if err := createLog(path, dir); err != nil {
			return nil, nil, err
		}
	} else if err := checkMagic(path); err != nil {
		return nil, nil, err
	}

	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, nil, fmt.Errorf("read %s: %w", logName, err)
	}
	goodLen, state, err := replayLog(raw)
	if err != nil {
		return nil, nil, err
	}
	if int64(len(raw)) != goodLen {
		// Drop the torn tail of an entry that can never have been acknowledged.
		tf, err := os.OpenFile(path, os.O_RDWR, compactFileMode)
		if err != nil {
			return nil, nil, fmt.Errorf("open %s for repair: %w", logName, err)
		}
		if err := tf.Truncate(goodLen); err != nil {
			tf.Close()
			return nil, nil, fmt.Errorf("truncate torn log tail: %w", err)
		}
		if err := tf.Sync(); err != nil {
			tf.Close()
			return nil, nil, fmt.Errorf("sync repaired %s: %w", logName, err)
		}
		if err := tf.Close(); err != nil {
			return nil, nil, err
		}
		if err := syncDir(dir); err != nil {
			return nil, nil, err
		}
	}

	f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
	if err != nil {
		return nil, nil, fmt.Errorf("open %s for append: %w", logName, err)
	}
	if _, err := f.Seek(0, io.SeekEnd); err != nil {
		f.Close()
		return nil, nil, err
	}
	return &store{dir: dir, f: f, size: goodLen}, state, nil
}

func createLog(path, dir string) error {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
	if err != nil {
		return fmt.Errorf("create %s: %w", logName, err)
	}
	frame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
	if _, err := f.Write(append([]byte(logMagic), frame...)); err != nil {
		f.Close()
		return fmt.Errorf("write %s header: %w", logName, err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return fmt.Errorf("sync %s: %w", logName, err)
	}
	if err := f.Close(); err != nil {
		return err
	}
	return syncDir(dir)
}

func mustMarshal(e *logEntry) []byte {
	b, err := json.Marshal(e)
	if err != nil {
		panic(err)
	}
	return b
}

// encodeFrame wraps a payload with its big-endian length and CRC32.
func encodeFrame(payload []byte) []byte {
	frame := make([]byte, 0, frameHeaderSize+len(payload)+frameCRCsSize)
	var hdr [4]byte
	binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
	frame = append(frame, hdr[:]...)
	frame = append(frame, payload...)
	var crc [4]byte
	binary.BigEndian.PutUint32(crc[:], crc32.Checksum(payload, crcTable))
	frame = append(frame, crc[:]...)
	return frame
}

func checkMagic(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("open %s: %w", logName, err)
	}
	defer f.Close()
	buf := make([]byte, len(logMagic))
	n, err := io.ReadFull(f, buf)
	if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
		return fmt.Errorf("read %s header: %w", logName, err)
	}
	if n < len(logMagic) || !bytes.Equal(buf, []byte(logMagic)) {
		return fmt.Errorf("%w: missing or foreign %s header", ErrCorrupt, logName)
	}
	return nil
}

// replayLog parses and validates the log, returning the byte length of the
// longest intact prefix and the reconstructed state.
func replayLog(raw []byte) (int64, *loadedState, error) {
	if !bytes.HasPrefix(raw, []byte(logMagic)) {
		return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
	}
	state := &loadedState{
		sources:  map[string]bool{},
		headers:  map[string]*headerState{},
		records:  map[string]*Record{},
		consumed: map[consumeToken]string{},
	}

	// The leading version record is the precondition for every later recovery
	// decision: nothing after the magic can be replayed or treated as a
	// truncatable tail until it has been read complete, checksummed and
	// confirmed to be a supported version. Validate it on its own so a torn or
	// bad first record can never look like an empty log that is safe to append
	// to.
	verEnd, err := readVersionRecord(raw, len(logMagic))
	if err != nil {
		return 0, nil, err
	}
	pos := verEnd

	for pos < len(raw) {
		// Need at least the length header.
		if len(raw)-pos < frameHeaderSize {
			return int64(pos), state, nil // torn length header of an unacked write
		}
		n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
		if n == 0 {
			return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
		}
		bodyStart := pos + frameHeaderSize
		frameEnd := bodyStart + n + frameCRCsSize
		if frameEnd > len(raw) {
			return int64(pos), state, nil // torn body/CRC of an unacked write
		}
		payload := raw[bodyStart : bodyStart+n]
		wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
		if crc32.Checksum(payload, crcTable) != wantCRC {
			if frameEnd == len(raw) {
				// Torn sectors of the final, unacknowledged frame.
				return int64(pos), state, nil
			}
			return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
		}
		var e logEntry
		if err := json.Unmarshal(payload, &e); err != nil {
			return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
		}
		if e.T == kindVersion {
			return 0, nil, fmt.Errorf("%w: unexpected version record at offset %d", ErrCorrupt, pos)
		}
		if err := applyEntry(state, &e); err != nil {
			return 0, nil, err
		}
		pos = frameEnd
	}
	return int64(pos), state, nil
}

// readVersionRecord reads and validates the log's first record at offset
// start, returning the offset just past it. A correct magic prefix alone is
// not a valid log: the version record must be fully present, its checksum
// must match, and it must name a supported version. Every other shape — a
// record cut short at end of file (one to three length bytes, or the length
// without the body and CRC), a complete final record with a bad checksum,
// invalid JSON, a non-version record, or an unsupported version — is a
// corrupt log, never a truncatable tail.
func readVersionRecord(raw []byte, start int) (int, error) {
	if len(raw)-start < frameHeaderSize {
		return 0, fmt.Errorf("%w: incomplete version record: only %d of %d length bytes after header",
			ErrCorrupt, len(raw)-start, frameHeaderSize)
	}
	n := int(binary.BigEndian.Uint32(raw[start : start+frameHeaderSize]))
	if n == 0 {
		return 0, fmt.Errorf("%w: zero-length version record at offset %d", ErrCorrupt, start)
	}
	bodyStart := start + frameHeaderSize
	frameEnd := bodyStart + n + frameCRCsSize
	if frameEnd > len(raw) {
		return 0, fmt.Errorf("%w: incomplete version record: length %d but only %d body/checksum bytes present",
			ErrCorrupt, n, len(raw)-bodyStart)
	}
	payload := raw[bodyStart : bodyStart+n]
	wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
	if crc32.Checksum(payload, crcTable) != wantCRC {
		return 0, fmt.Errorf("%w: checksum mismatch in version record at offset %d", ErrCorrupt, start)
	}
	var e logEntry
	if err := json.Unmarshal(payload, &e); err != nil {
		return 0, fmt.Errorf("%w: invalid version record at offset %d: %v", ErrCorrupt, start, err)
	}
	if e.T != kindVersion {
		return 0, fmt.Errorf("%w: first record is %q, not a version record", ErrCorrupt, e.T)
	}
	if e.V != currentLogV {
		return 0, fmt.Errorf("%w: unsupported log version %d", ErrCorrupt, e.V)
	}
	return frameEnd, nil
}

// entryCarriesConsumption reports whether a non-success entry smuggles any
// consumption field, which is always corrupt.
func entryCarriesConsumption(e *logEntry) bool {
	return e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0 ||
		e.ConsumeKey != "" || e.ConsumeBy != ""
}

// acceptConsumption validates the triple consumed by a success result or
// compacted state entry and records it in s.consumed. The triple must
// identify the record's own message and be consumed by that message.
//
// Logs written by older builds carry the consumption as one NUL-joined
// consumeKey. Such an entry is accepted only when that legacy key matches the
// record's own triple; it is the record's own triple that is marked consumed,
// never the ambiguous flattened string — so two distinct paths that happened
// to share one old flattened key each consume only themselves. A legacy key
// that does not match its record is an inconsistent record and rejected.
func acceptConsumption(s *loadedState, rec *Record, e *logEntry, corrupt func(string, ...any) error) (consumeToken, error) {
	m := rec.Msg.Message
	if e.ConsumeBy != e.ID {
		return consumeToken{}, corrupt("success entry for %q is marked consumed by %q", e.ID, e.ConsumeBy)
	}
	token := newConsumeToken(m.From, m.To, m.Nonce)
	hasTriple := e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0
	switch {
	case hasTriple:
		if e.ConsumeKey != "" {
			return consumeToken{}, corrupt("success entry for %q carries both a triple and a legacy consume key", e.ID)
		}
		if e.ConsumeFrom != m.From || e.ConsumeTo != m.To || e.ConsumeNonce != m.Nonce {
			return consumeToken{}, corrupt("success entry for %q carries mismatched nonce consumption: %q -> %q nonce %d", e.ID, e.ConsumeFrom, e.ConsumeTo, e.ConsumeNonce)
		}
	case e.ConsumeKey != "":
		if want := legacyNonceKey(m.From, m.To, m.Nonce); e.ConsumeKey != want {
			return consumeToken{}, corrupt("success entry for %q carries a legacy consume key for a different path", e.ID)
		}
	default:
		return consumeToken{}, corrupt("success entry for %q carries no nonce consumption", e.ID)
	}
	if winner, taken := s.consumed[token]; taken {
		return consumeToken{}, corrupt("nonce %s already consumed by %q while accepting %q", token, winner, e.ID)
	}
	s.consumed[token] = e.ID
	return token, nil
}

// recoveryKind distinguishes the two log record shapes that can carry a
// message's post-processing state. They are never merged into one kind: a
// plain result ("result") is one incremental outcome and must follow the
// attempts-jump and monotonic-time rules, while a compacted snapshot ("state")
// stores the full current status after >=1 attempts. recoveryKind only selects
// the record-category wording in corrupt errors and the kind-specific
// acceptance checks; both kinds then run the *same* per-status rules.
//
// waitingNoun is the word the historical waiting errors use ("result" for a
// plain result, "state" for a snapshot); entryNoun is the word the historical
// success/terminal errors use ("entry" for a plain result, "state" for a
// snapshot). Keeping them separate preserves every corrupt message verbatim.
type recoveryKind struct {
	waitingNoun string
	entryNoun   string
}

var (
	recoveryResult = recoveryKind{waitingNoun: "result", entryNoun: "entry"}
	recoveryState  = recoveryKind{waitingNoun: "state", entryNoun: "state"}
)

// validateRecoveryStatus is the first shared check for a result entry and a
// compacted state entry: the carried status must be one of the known statuses
// and must never be pending (pending is established by the submit entry, not
// by a post-processing record).
func validateRecoveryStatus(e *logEntry, rk recoveryKind) error {
	corrupt := func(msg string, args ...any) error {
		return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
	}
	if !validStatus(e.Status) || e.Status == StatusPending {
		return corrupt("bad %s status %q for %q", rk.waitingNoun, e.Status, e.ID)
	}
	return nil
}

// acceptRecoveryStatus is the second shared check, run after the
// kind-specific acceptance rules (including the snapshot's >=1-attempts
// requirement): waiting must carry the canonical retry schedule (with the
// sole legacy-overflow exception repaired in memory) and no consumption,
// success must keep no retry time and consume its own (from,to,nonce)
// attributed to itself, and terminal failures carry neither a retry time nor
// consumption fields. The repaired retry time of a legacy overflowed schedule
// is written back onto e.
func acceptRecoveryStatus(s *loadedState, rec *Record, e *logEntry, rk recoveryKind) error {
	corrupt := func(msg string, args ...any) error {
		return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
	}
	switch e.Status {
	case StatusWaiting:
		scheduled, ok := validWaitingSchedule(e.Now, e.Attempts, e.NextRetry)
		if !ok {
			return corrupt("waiting %s has wrong retry schedule for %q", rk.waitingNoun, e.ID)
		}
		// Repair a legacy overflowed (negative) retry to the ceiling in
		// memory; the next compaction writes the repaired value back.
		e.NextRetry = scheduled
		if entryCarriesConsumption(e) {
			return corrupt("waiting %s for %q carries nonce consumption fields", rk.waitingNoun, e.ID)
		}
	case StatusSuccess:
		if e.NextRetry != 0 {
			return corrupt("success %s for %q carries retry time", rk.entryNoun, e.ID)
		}
		if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
			return err
		}
	default: // terminal failure kinds
		if e.NextRetry != 0 || entryCarriesConsumption(e) {
			return corrupt("terminal %s for %q carries scheduling/consume fields", rk.entryNoun, e.ID)
		}
	}
	return nil
}

// applyRecoveredState copies the validated post-processing state of one result
// or compacted-state entry onto the record. Both record kinds describe the
// same message state the same way, so the assignment lives in one place.
func applyRecoveredState(s *loadedState, rec *Record, e *logEntry) {
	rec.Attempts = e.Attempts
	rec.LastProcAt = e.Now
	rec.Status = e.Status
	rec.Reason = e.Reason
	rec.NextRetry = e.NextRetry
	if e.Now > s.now {
		s.now = e.Now
	}
}

func applyEntry(s *loadedState, e *logEntry) error {
	corrupt := func(msg string, args ...any) error {
		return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
	}
	switch e.T {
	case kindSource:
		if e.Chain == "" {
			return corrupt("source entry with empty chain")
		}
		s.sources[e.Chain] = true
	case kindHeader:
		if e.Chain == "" || e.Height < 0 {
			return corrupt("bad header entry: %+v", e)
		}
		// Replay is permissive: historical same-height coverage is never
		// rejected as a conflict, and recovery relies only on the header
		// records actually kept in the log. The latest header is the last one
		// written; the highest trusted header is the max-height trusted one,
		// with ties going to the later write (matching old overwrite
		// semantics). Neither is fabricated from lost history.
		hs := s.headers[e.Chain]
		if hs == nil {
			hs = &headerState{}
			s.headers[e.Chain] = hs
		}
		hs.latest = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
		if e.Trusted && (hs.trusted == nil || e.Height >= hs.trusted.Height) {
			t := hs.latest
			hs.trusted = &t
		}
	case kindSubmit:
		if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
			return corrupt("bad submit entry: %+v", e)
		}
		if _, dup := s.records[e.ID]; dup {
			return corrupt("duplicate submit for id %q", e.ID)
		}
		if e.Seq != s.nextSeq {
			return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
		}
		s.records[e.ID] = &Record{
			Msg: Envelope{
				Message: Message{
					ID:      e.ID,
					From:    e.From,
					To:      e.To,
					Nonce:   e.Nonce,
					Payload: e.Payload,
					ProofAt: e.ProofAt,
				},
				ExpiresAt: e.ExpiresAt,
			},
			Status: StatusPending,
			Reason: "awaiting first processing",
			Seq:    e.Seq,
		}
		s.nextSeq++
	case kindResult:
		// A plain result is one incremental processing outcome: it applies
		// only to a known, still non-terminal record, attempts must advance by
		// exactly one, and the processing time must never move backwards. The
		// per-status validation (waiting schedule, success consumption,
		// terminal fields) is shared with compacted state entries.
		rec, ok := s.records[e.ID]
		if !ok {
			return corrupt("result for unknown id %q", e.ID)
		}
		if isTerminal(rec.Status) {
			return corrupt("result for terminal id %q", e.ID)
		}
		if rec.Attempts > 0 && e.Now < rec.LastProcAt {
			return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
		}
		if e.Attempts != rec.Attempts+1 {
			return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
		}
		if err := validateRecoveryStatus(e, recoveryResult); err != nil {
			return err
		}
		if err := acceptRecoveryStatus(s, rec, e, recoveryResult); err != nil {
			return err
		}
		applyRecoveredState(s, rec, e)
	case kindState:
		// A compacted snapshot stores the message's full current status after
		// >=1 attempts: it may restore an attempt count greater than one
		// directly, but it applies only to a known record and never twice for
		// the same message. The per-status validation is shared with plain
		// result entries; the two kinds stay distinct on disk.
		rec, ok := s.records[e.ID]
		if !ok {
			return corrupt("state for unknown id %q", e.ID)
		}
		if rec.Attempts != 0 {
			return corrupt("duplicate state for id %q", e.ID)
		}
		if err := validateRecoveryStatus(e, recoveryState); err != nil {
			return err
		}
		if e.Attempts < 1 {
			return corrupt("state with zero attempts for %q", e.ID)
		}
		if err := acceptRecoveryStatus(s, rec, e, recoveryState); err != nil {
			return err
		}
		applyRecoveredState(s, rec, e)
	case kindAdvance:
		if e.Now < s.now {
			return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
		}
		s.now = e.Now
	default:
		return corrupt("unknown record type %q", e.T)
	}
	return nil
}

func validStatus(s string) bool {
	switch s {
	case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

// validWaitingSchedule validates the retry instant recorded on a waiting
// result or compacted-state entry against the processing time and attempt
// number. The canonical schedule is nextRetryAt(now, attempts): now plus the
// backoff delay, saturated at math.MaxInt64 when it would overflow.
//
// Logs written by older builds contain the raw now+delay even near the
// ceiling, where the addition wrapped around to a value below now (typically
// negative). That exact wrapped value is the only non-canonical schedule
// accepted: it proves the entry came from the old scheduler rather than from
// arbitrary corruption, and it is repaired in memory to the saturated
// ceiling, which the next compaction persists. Any other retry time — zero,
// an arbitrary instant, or a value before the processing time that is not the
// exact legacy overflow — is rejected as corrupt.
func validWaitingSchedule(now int64, attempts int, stored int64) (int64, bool) {
	canonical := nextRetryAt(now, attempts)
	if stored == canonical {
		return stored, true
	}
	wrapped := now + nextRetryDelay(attempts)
	if wrapped < now && stored == wrapped {
		return math.MaxInt64, true
	}
	return 0, false
}

func (s *store) close() error {
	if s.f == nil {
		return nil
	}
	err := s.f.Sync()
	cerr := s.f.Close()
	s.f = nil
	if err != nil {
		return err
	}
	return cerr
}

// forceClose releases the file without the final sync after a failed write.
func (s *store) forceClose() {
	if s.f == nil {
		return
	}
	s.f.Close()
	s.f = nil
}

// append writes one framed, checksummed, fsynced record.
func (s *store) append(e *logEntry) error {
	if s.injectErr != nil {
		return s.injectErr
	}
	body, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("encode log entry: %w", err)
	}
	if _, err := s.f.Write(encodeFrame(body)); err != nil {
		return fmt.Errorf("write %s: %w", logName, err)
	}
	if err := s.f.Sync(); err != nil {
		return fmt.Errorf("sync %s: %w", logName, err)
	}
	if info, err := s.f.Stat(); err == nil {
		s.size = info.Size()
	} else {
		s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
	}
	return nil
}

// needsCompaction reports whether the log crossed the compaction threshold.
func (s *store) needsCompaction() bool {
	return s.size > compactThreshold && s.snap != nil
}

func (s *store) appendRegisterSource(chain string) error {
	return s.append(&logEntry{T: kindSource, Chain: chain})
}

func (s *store) appendHeader(h Header) error {
	return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
}

func (s *store) appendSubmit(rec *Record) error {
	m := rec.Msg.Message
	return s.append(&logEntry{
		T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
		Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
	})
}

// appendResult records one processing outcome. On success the consumed triple
// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
// durable record, committing together atomically. token is nil for every
// non-success status.
func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, token *consumeToken, consumeBy string) error {
	e := &logEntry{
		T: kindResult, Now: now, ID: rec.Msg.Message.ID,
		Status: status, Reason: reason, Attempts: attempts,
	}
	if status == StatusSuccess {
		if token == nil || consumeBy == "" {
			return fmt.Errorf("internal error: success result for %q missing nonce consumption", rec.Msg.Message.ID)
		}
		e.ConsumeFrom = token.from
		e.ConsumeTo = token.to
		e.ConsumeNonce = token.nonce
		e.ConsumeBy = consumeBy
	}
	return s.append(e)
}

// appendWaiting records a waiting outcome with a retry instant the queue
// layer already computed and saturated, so the log never carries an overflowed
// negative schedule.
func (s *store) appendWaiting(now int64, rec *Record, reason string, attempts int, nextRetry int64) error {
	return s.append(&logEntry{
		T: kindResult, Now: now, ID: rec.Msg.Message.ID,
		Status: StatusWaiting, Reason: reason, Attempts: attempts, NextRetry: nextRetry,
	})
}

func (s *store) appendAdvance(now int64) error {
	return s.append(&logEntry{T: kindAdvance, Now: now})
}

// compact atomically replaces the log with a deterministic snapshot of live
// state. It must run while Queue.mu is held (no concurrent mutation), and only
// after in-memory state reflects every acknowledged append.
func (s *store) compact(state *loadedState) error {
	entries := []*logEntry{{T: kindVersion, V: currentLogV}}

	chains := make([]string, 0, len(state.sources))
	for c := range state.sources {
		chains = append(chains, c)
	}
	sort.Strings(chains)
	for _, c := range chains {
		entries = append(entries, &logEntry{T: kindSource, Chain: c})
	}

	headerChains := make([]string, 0, len(state.headers))
	for c := range state.headers {
		headerChains = append(headerChains, c)
	}
	sort.Strings(headerChains)
	for _, c := range headerChains {
		hs := state.headers[c]
		// Write the highest trusted header first, then the latest header when
		// it differs. Replay reconstructs latest as the last entry and the
		// highest trusted as the max-height trusted entry, so this order
		// restores both exactly.
		if hs.trusted != nil {
			entries = append(entries, &logEntry{T: kindHeader, Chain: hs.trusted.Chain, Height: hs.trusted.Height, Root: hs.trusted.Root, Trusted: hs.trusted.Trusted})
		}
		if hs.trusted == nil || hs.latest != *hs.trusted {
			entries = append(entries, &logEntry{T: kindHeader, Chain: hs.latest.Chain, Height: hs.latest.Height, Root: hs.latest.Root, Trusted: hs.latest.Trusted})
		}
	}

	seqs := make([]int64, 0, len(state.records))
	bySeq := make(map[int64]*Record, len(state.records))
	for _, rec := range state.records {
		seqs = append(seqs, rec.Seq)
		bySeq[rec.Seq] = rec
	}
	sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
	for _, seq := range seqs {
		rec := bySeq[seq]
		m := rec.Msg.Message
		entries = append(entries, &logEntry{
			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
		})
		if rec.Attempts > 0 {
			re := &logEntry{
				T: kindState, Now: rec.LastProcAt, ID: m.ID,
				Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
			}
			if rec.Status == StatusWaiting {
				re.NextRetry = rec.NextRetry
			}
			if rec.Status == StatusSuccess {
				re.ConsumeFrom = m.From
				re.ConsumeTo = m.To
				re.ConsumeNonce = m.Nonce
				re.ConsumeBy = m.ID
			}
			entries = append(entries, re)
		}
	}
	if state.now > 0 {
		entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
	}

	tmp := filepath.Join(s.dir, logName+".compact")
	f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
	if err != nil {
		return err
	}
	abort := func(err error) error {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if _, err := f.WriteString(logMagic); err != nil {
		return abort(err)
	}
	for _, e := range entries {
		body, err := json.Marshal(e)
		if err != nil {
			return abort(err)
		}
		if _, err := f.Write(encodeFrame(body)); err != nil {
			return abort(err)
		}
	}
	if err := f.Sync(); err != nil {
		return abort(err)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := syncDir(s.dir); err != nil {
		return err
	}
	nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
	if err != nil {
		return err
	}
	if _, err := nf.Seek(0, io.SeekEnd); err != nil {
		nf.Close()
		return err
	}
	s.f.Close()
	s.f = nf
	if info, err := nf.Stat(); err == nil {
		s.size = info.Size()
	}
	return nil
}

// syncDir fsyncs a directory so that file creation and rename survive a crash.
func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return fmt.Errorf("open directory for sync: %w", err)
	}
	defer d.Close()
	if err := d.Sync(); err != nil {
		return fmt.Errorf("sync directory %s: %w", dir, err)
	}
	return nil
}

