1	// Command relayproof is the 跨链消息与轻客户端验证服务 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"os"
10	
11		"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
12	)
13	
14	func main() {
15		if len(os.Args) < 2 {
16			runDemo()
17			return
18		}
19		switch os.Args[1] {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("relayproof 0.2.0")
24		case "queue":
25			runQueue(os.Args[2:])
26		case "verify":
27			if err := runVerify(os.Args[2:]); err != nil {
28				fmt.Fprintf(os.Stderr, "error: %v\n", err)
29				os.Exit(1)
30			}
31		case "help", "-h", "--help":
32			usage()
33		default:
34			fmt.Fprintf(os.Stderr, "unknown command %q\n", os.Args[1])
35			usage()
36			os.Exit(2)
37		}
38	}
39	
40	func usage() {
41		fmt.Println(`usage: relayproof <command> [flags]
42	
43	commands:
44	  demo                         run the in-memory verification demo
45	  version                      print version
46	  queue                        manage the durable local message queue
47	  verify [--state DIR]         run the deterministic end-to-end verification
48	  help                         show this help
49	
50	queue subcommands (all take --state DIR):
51	  register-source --chain C
52	  header --chain C --height N --root R [--trusted]
53	  submit --id ID --from C --to C --nonce N --proof-at H --payload P [--expires-at MS]
54	  advance --now MS
55	  query [--id ID]
56	
57	times are Unix milliseconds; --expires-at 0 (default) means never expire.`)
58	}
59	
60	func runQueue(args []string) {
61		if len(args) == 0 {
62			fmt.Fprintln(os.Stderr, "queue requires a subcommand: register-source|header|submit|advance|query")
63			os.Exit(2)
64		}
65		sub, rest := args[0], args[1:]
66		var err error
67		switch sub {
68		case "register-source":
69			err = queueCmdRegisterSource(rest)
70		case "header":
71			err = queueCmdHeader(rest)
72		case "submit":
73			err = queueCmdSubmit(rest)
74		case "advance":
75			err = queueCmdAdvance(rest)
76		case "query":
77			err = queueCmdQuery(rest)
78		default:
79			fmt.Fprintf(os.Stderr, "unknown queue subcommand %q\n", sub)
80			os.Exit(2)
81		}
82		if err != nil {
83			fmt.Fprintf(os.Stderr, "error: %v\n", err)
84			os.Exit(exitCode(err))
85		}
86	}
87	
88	func exitCode(err error) int {
89		switch {
90		case errors.Is(err, relayproof.ErrLocked):
91			return 11
92		case errors.Is(err, relayproof.ErrCorrupt):
93			return 12
94		case errors.Is(err, relayproof.ErrConflict):
95			return 13
96		case errors.Is(err, relayproof.ErrHeaderConflict):
97			return 16
98		case errors.Is(err, relayproof.ErrTerminal):
99			return 14
100		case errors.Is(err, relayproof.ErrInvalidArg):
101			return 2
102		case errors.Is(err, relayproof.ErrStorage):
103			return 15
104		default:
105			return 1
106		}
107	}
108	
109	type globalFlags struct {
110		state string
111	}
112	
113	func newQueueFlagSet(name string, g *globalFlags) *flag.FlagSet {
114		fs := flag.NewFlagSet(name, flag.ContinueOnError)
115		fs.SetOutput(os.Stderr)
116		fs.StringVar(&g.state, "state", "", "state directory (required)")
117		return fs
118	}
119	
120	func (g *globalFlags) mustState() {
121		if g.state == "" {
122			fmt.Fprintln(os.Stderr, "error: --state is required")
123			os.Exit(2)
124		}
125	}
126	
127	func queueCmdRegisterSource(rest []string) error {
128		g := &globalFlags{}
129		fs := newQueueFlagSet("register-source", g)
130		chain := fs.String("chain", "", "source chain name (required)")
131		if err := fs.Parse(rest); err != nil {
132			return err
133		}
134		if *chain == "" {
135			return fmt.Errorf("%w: --chain is required", relayproof.ErrInvalidArg)
136		}
137		g.mustState()
138		q, err := relayproof.Open(g.state)
139		if err != nil {
140			return err
141		}
