13	func openTempQueue(t *testing.T) (*Queue, string) {
14		t.Helper()
15		dir := t.TempDir()
16		q, err := Open(dir)
17		if err != nil {
18			t.Fatalf("Open: %v", err)
19		}
20		return q, dir
21	}
22	
23	func env(id, from, to string, nonce uint64, proofAt, expiresAt int64) Envelope {
24		return Envelope{
25			Message:   Message{ID: id, From: from, To: to, Nonce: nonce, Payload: "p-" + id, ProofAt: proofAt},
26			ExpiresAt: expiresAt,
27		}
28	}
29	
30	func statusOf(t *testing.T, q *Queue, id string) Record {
31		t.Helper()
32		got, ok := q.Query(id)
33		if !ok {
34			t.Fatalf("missing record %s", id)
35		}
36		return Record{
37			Msg:       Envelope{Message: Message{ID: got.ID, From: got.From, To: got.To, Nonce: got.Nonce, Payload: got.Payload, ProofAt: got.ProofAt}, ExpiresAt: got.ExpiresAt},
38			Status:    got.Status,
39			Reason:    got.Reason,
40			NextRetry: got.NextRetry,
41			Attempts:  got.Attempts,
42		}
43	}
44	
45	// End-to-end happy path: waiting until a trusted header covers the proof
46	// height, then delivery with nonce consumption.
47	func TestHappyPath(t *testing.T) {
48		q, _ := openTempQueue(t)
49		defer q.Close()
50	
51		if err := q.RegisterSource("a"); err != nil {
52			t.Fatal(err)
53		}
54		if _, err := q.Submit(env("m1", "a", "b", 1, 100, 0)); err != nil {
55			t.Fatal(err)
56		}
57	
58		// First advance: registered but no header yet -> waiting, retry at +1s.
59		rep, err := q.Advance(1000)
60		if err != nil {
61			t.Fatal(err)
62		}
63		if len(rep.Results) != 1 || rep.Results[0].Status != StatusWaiting {
64			t.Fatalf("want one waiting result, got %+v", rep.Results)
65		}
66		r := statusOf(t, q, "m1")
67		if r.Status != StatusWaiting || r.NextRetry != 2000 || r.Attempts != 1 {
68			t.Fatalf("want waiting retry=2000 attempts=1, got %+v", r)
69		}
70	
71		// Trusted header still short of proof height.
72		if err := q.UpsertHeader(Header{Chain: "a", Height: 99, Trusted: true}); err != nil {
73			t.Fatal(err)
74		}
75		if _, err := q.Advance(2000); err != nil {
76			t.Fatal(err)
77		}
78		r = statusOf(t, q, "m1")
79		if r.Status != StatusWaiting || r.NextRetry != 4000 || r.Attempts != 2 {
80			t.Fatalf("want still waiting retry=4000, got %+v", r)
81		}
82	
83		// Header covering the proof height, but retry time must not be bypassed.
84		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true}); err != nil {
85			t.Fatal(err)
86		}
87		if _, err := q.Advance(3000); err != nil {
88			t.Fatal(err)
89		}
90		r = statusOf(t, q, "m1")
91		if r.Status != StatusWaiting || r.NextRetry != 4000 {
92			t.Fatalf("header must not bypass retry schedule, got %+v", r)
93		}
94	
95		rep, err = q.Advance(4000)
96		if err != nil {
97			t.Fatal(err)
98		}
99		if len(rep.Results) != 1 || rep.Results[0].Status != StatusSuccess {
100			t.Fatalf("want success, got %+v", rep.Results)
101		}
102		r = statusOf(t, q, "m1")
103		if r.Status != StatusSuccess || r.NextRetry != 0 {
104			t.Fatalf("want terminal success without retry, got %+v", r)
105		}
106		if got := q.consumed[newConsumeToken("a", "b", 1)]; got != "m1" {
107			t.Fatalf("nonce not consumed by m1: %q", got)
108		}
109	}
110	
111	// Untrusted headers keep the message waiting; a later trusted one unblocks.
112	func TestUntrustedThenTrustedHeader(t *testing.T) {
113		q, _ := openTempQueue(t)
114		defer q.Close()
115		q.RegisterSource("a")
116		q.Submit(env("m", "a", "b", 1, 10, 0))
117	
118		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: false})
119		q.Advance(1000)
120		if r := statusOf(t, q, "m"); r.Status != StatusWaiting {
121			t.Fatalf("untrusted header: want waiting, got %s", r.Status)
122		}
123		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
124		q.Advance(2000)
125		if r := statusOf(t, q, "m"); r.Status != StatusSuccess {
126			t.Fatalf("trusted header: want success, got %s (%s)", r.Status, r.Reason)
127		}
128	}
129	
