459				t.Fatalf("position %d: want %s success, got %s %s", i, want, res.ID, res.Status)
460			}
461		}
462		if err := q.Close(); err != nil {
463			t.Fatal(err)
464		}
465	
466		// Reopen: state must be restored and successes must not deliver again.
467		q2, err := Open(dir)
468		if err != nil {
469			t.Fatal(err)
470		}
471		defer q2.Close()
472		if q2.Now() != 1000 {
473			t.Fatalf("restored now: want 1000 got %d", q2.Now())
474		}
475		for i := 0; i < 5; i++ {
476			r := statusOf(t, q2, fmt.Sprintf("m%02d", i))
477			if r.Status != StatusSuccess {
478				t.Fatalf("m%02d lost terminal state: %s", i, r.Status)
479			}
480		}
481		rep, err = q2.Advance(2000)
482		if err != nil {
483			t.Fatal(err)
484		}
485		for _, res := range rep.Results {
486			t.Fatalf("delivered messages processed again: %+v", res)
487		}
488	
489		// Waiting order also survives a restart and stays in submission order.
490		q2.Submit(env("w2", "a", "b", 20, 9999, 0))
491		q2.Submit(env("w1", "a", "b", 21, 9999, 0))
492		q2.Advance(2000)
493		if err := q2.Close(); err != nil {
494			t.Fatal(err)
495		}
496		q3, err := Open(dir)
497		if err != nil {
498			t.Fatal(err)
499		}
500		defer q3.Close()
501		if len(q3.order) != 2 || q3.order[0] != "w2" || q3.order[1] != "w1" {
502			t.Fatalf("waiting order not restored: %v", q3.order)
503		}
504		r := statusOf(t, q3, "w1")
505		if r.Status != StatusWaiting || r.NextRetry != 3000 {
506			t.Fatalf("retry schedule not restored: %+v", r)
507		}
508	}
