579		}
580		q.RegisterSource("a")
581		q.Submit(env("m1", "a", "b", 1, 10, 0))
582		q.Submit(env("m2", "a", "b", 2, 10, 0))
583		q.Close()
584	
585		raw, err := os.ReadFile(filepath.Join(dir, logName))
586		if err != nil {
587			t.Fatal(err)
588		}
589	
590		// Torn tail: cut the last frame in half; reopen truncates and keeps m1.
591		torn := make([]byte, len(raw)-3)
592		copy(torn, raw)
593		tornDir := t.TempDir()
594		os.WriteFile(filepath.Join(tornDir, logName), torn, 0o600)
595		qt, err := Open(tornDir)
596		if err != nil {
