701	// WAL compaction preserves the exact logical state and lets the log shrink.
702	func TestCompaction(t *testing.T) {
703		dir := t.TempDir()
704		q, err := Open(dir)
705		if err != nil {
706			t.Fatal(err)
707		}
708		q.RegisterSource("a")
709		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
710		for i := 0; i < 30; i++ {
711			q.Submit(env(fmt.Sprintf("m%02d", i), "a", "b", uint64(i), 10, 0))
712		}
713		q.Advance(1000)
714		q.Submit(env("w1", "a", "b", 99, 5000, 0))
715		q.Advance(2000) // w1 waiting, NextRetry=3000
716		q.Advance(3000) // w1 waiting again (attempt 2), NextRetry=5000
717	
718		if err := q.store.compact(q.snapshot()); err != nil {
719			t.Fatal(err)
720		}
721		q.Close()
722	
723		q2, err := Open(dir)
724		if err != nil {
725			t.Fatalf("reopen compacted log: %v", err)
726		}
727		defer q2.Close()
728		for i := 0; i < 30; i++ {
729			if r := statusOf(t, q2, fmt.Sprintf("m%02d", i)); r.Status != StatusSuccess {
730				t.Fatalf("m%02d: want success got %s", i, r.Status)
731			}
732		}
733		r := statusOf(t, q2, "w1")
734		if r.Status != StatusWaiting || r.NextRetry != 5000 || r.Attempts != 2 {
735			t.Fatalf("w1 schedule lost: %+v", r)
736		}
737		if len(q2.consumed) != 30 {
738			t.Fatalf("consumed nonces lost: %d", len(q2.consumed))
739		}
740		if q2.Now() != 3000 {
741			t.Fatalf("processing time lost: %d", q2.Now())
742		}
743		// Equal-time re-advance keeps backoff (next retry 5000) untouched.
744		if _, err := q2.Advance(3000); err != nil {
745			t.Fatal(err)
746		}
747		r = statusOf(t, q2, "w1")
748		if r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != 5000 {
749			t.Fatalf("w1 should keep waiting with unchanged schedule: %+v", r)
750		}
751	}
