// Expired and replay terminal reasons survive restart exactly.
func TestTerminalReasonsSurviveRestart(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	q.RegisterSource("a")
	q.Submit(env("m", "a", "b", 1, 10, 2000))
	q.Advance(1000)
	q.Advance(2000)
	q.Close()

	q2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer q2.Close()
