115	// TestSharedRecoveryRulesRejectSameShapes verifies that every per-status rule
116	// rejects a result entry and a compacted state entry identically: the same
117	// bad shape is corrupt either way, and the error keeps the category and the
118	// message id recognizable.
119	func TestSharedRecoveryRulesRejectSameShapes(t *testing.T) {
120		cases := []struct {
121			name    string
122			entries func(kind string) []*logEntry
123			want    func(label, successNoun string) []string
124		}{
125			{
126				name: "unknown status",
127				entries: func(kind string) []*logEntry {
128					r := waitingRecoveryRecord(kind)
129					r.Status = "bogus"
130					return append(waitingRecoveryBase(), r)
131				},
132				want: func(label, _ string) []string {
133					return []string{fmt.Sprintf("bad %s status", label), `"bogus"`, `"w"`}
134				},
135			},
136			{
137				name: "pending status",
138				entries: func(kind string) []*logEntry {
139					r := waitingRecoveryRecord(kind)
140					r.Status = StatusPending
141					return append(waitingRecoveryBase(), r)
142				},
143				want: func(label, _ string) []string {
144					return []string{fmt.Sprintf("bad %s status", label), StatusPending, `"w"`}
145				},
146			},
147			{
148				name: "waiting wrong retry schedule",
149				entries: func(kind string) []*logEntry {
150					r := waitingRecoveryRecord(kind)
151					r.NextRetry = 4242
152					return append(waitingRecoveryBase(), r)
153				},
154				want: func(label, _ string) []string {
155					return []string{fmt.Sprintf("waiting %s has wrong retry schedule", label), `"w"`}
156				},
157			},
158			{
159				name: "waiting carries nonce consumption",
160				entries: func(kind string) []*logEntry {
161					r := waitingRecoveryRecord(kind)
162					r.ConsumeBy = "w"
163					return append(waitingRecoveryBase(), r)
164				},
165				want: func(label, _ string) []string {
166					return []string{fmt.Sprintf("waiting %s", label), "carries nonce consumption fields", `"w"`}
167				},
168			},
169			{
170				name: "success carries retry time",
171				entries: func(kind string) []*logEntry {
172					r := successRecoveryRecord(kind)
173					r.NextRetry = 7
174					return append(successRecoveryBase(), r)
175				},
176				want: func(_, successNoun string) []string {
177					return []string{fmt.Sprintf("success %s for %q carries retry time", successNoun, "m")}
178				},
179			},
180			{
181				name: "success without nonce consumption",
182				entries: func(kind string) []*logEntry {
183					r := successRecoveryRecord(kind)
184					r.ConsumeFrom, r.ConsumeTo, r.ConsumeNonce = "", "", 0
185					return append(successRecoveryBase(), r)
186				},
187				want: func(_, _ string) []string {
188					return []string{"success entry", "carries no nonce consumption", `"m"`}
189				},
190			},
191			{
192				name: "success mismatched triple",
193				entries: func(kind string) []*logEntry {
194					r := successRecoveryRecord(kind)
195					r.ConsumeNonce = 9
196					return append(successRecoveryBase(), r)
197				},
198				want: func(_, _ string) []string {
199					return []string{"success entry", "mismatched nonce consumption", `"m"`}
200				},
201			},
202			{
203				name: "success attributed to another message",
204				entries: func(kind string) []*logEntry {
205					r := successRecoveryRecord(kind)
206					r.ConsumeBy = "x"
207					return append(successRecoveryBase(), r)
208				},
209				want: func(_, _ string) []string {
210					return []string{"success entry", "marked consumed by", `"x"`, `"m"`}
211				},
212			},
213			{
214				name: "same triple consumed twice",
215				entries: func(kind string) []*logEntry {
216					base := []*logEntry{
217						{T: kindSource, Chain: "a"},
218						{T: kindHeader, Chain: "a", Height: 100, Root: "0x100", Trusted: true},
219						{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, ProofAt: 10},
220						{T: kindSubmit, Seq: 1, ID: "n", From: "a", To: "b", Nonce: 1, ProofAt: 10},
221					}
222					first := &logEntry{
223						T: kind, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok", Attempts: 1,
224						ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
225					}
226					second := &logEntry{
227						T: kind, Now: 1000, ID: "n", Status: StatusSuccess, Reason: "ok", Attempts: 1,
228						ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "n",
229					}
230					return append(base, first, second)
231				},
232				want: func(_, _ string) []string {
233					return []string{"already consumed by", `"m"`, `"n"`}
234				},
235			},
236			{
237				name: "terminal carries retry time",
