241					return append(terminalRecoveryBase(), r)
242				},
243				want: func(_, successNoun string) []string {
244					return []string{fmt.Sprintf("terminal %s for %q carries scheduling/consume fields", successNoun, "t")}
245				},
246			},
247			{
248				name: "terminal carries consumption",
249				entries: func(kind string) []*logEntry {
250					r := terminalRecoveryRecord(kind)
251					r.ConsumeNonce = 1
252					return append(terminalRecoveryBase(), r)
253				},
254				want: func(_, successNoun string) []string {
255					return []string{fmt.Sprintf("terminal %s for %q carries scheduling/consume fields", successNoun, "t")}
256				},
257			},
258		}
259	
260		for _, kind := range []struct {
261			t           string
262			label       string
263			successNoun string
264		}{
265			{kindResult, "result", "entry"},
266			{kindState, "state", "state"},
267		} {
268			for _, tc := range cases {
