34	// Unit checks for the saturating scheduler.
35	func TestNextRetryAtSaturates(t *testing.T) {
36		cases := []struct {
37			name    string
38			now     int64
39			attempt int
40			want    int64
41		}{
42			{"normal first", 1000, 1, 2000},
43			{"normal capped interval", 500_000, 7, 560_000},
44			{"exactly representable at ceiling", ceiling - 60_000, 7, ceiling},
45			{"one millisecond short stays exact", ceiling - 60_001, 7, ceiling - 1},
46			{"first interval overflows", ceiling - 500, 1, ceiling},
47			{"processing at the ceiling", ceiling, 1, ceiling},
48			{"capped interval at ceiling", ceiling, 7, ceiling},
49		}
50		for _, c := range cases {
51			t.Run(c.name, func(t *testing.T) {
52				got := nextRetryAt(c.now, c.attempt)
53				if got != c.want {
54					t.Fatalf("nextRetryAt(%d,%d) = %d, want %d", c.now, c.attempt, got, c.want)
55				}
56				if got < c.now {
57					t.Fatalf("retry %d must never precede processing time %d", got, c.now)
58				}
59			})
60		}
61	}
