133	// When the retry reaches the ceiling, a covering trusted header lets the
134	// message succeed by the normal rules, consuming the nonce on its second
135	// attempt.
136	func TestCeilingRetryWithCoveringHeaderSucceeds(t *testing.T) {
137		q, _ := openTempQueue(t)
