118			}
119		}
120		if got["dup"].Status != StatusReplay || !strings.Contains(got["dup"].Reason, "c1") {
121			t.Fatalf("dup must be replay attributed to c1, got %+v", got["dup"])
122		}
123		if len(q.consumed) != 4 {
124			t.Fatalf("want exactly 4 consumed triples, got %d: %v", len(q.consumed), q.consumed)
125		}
126		// Queries keep the full, unmodified chain names.
127		if r, _ := q.Query("n1"); r.From != "a\x00b" || r.To != "c" {
128			t.Fatalf("NUL chain name rewritten: %q -> %q", r.From, r.To)
129		}
130		if r, _ := q.Query("c2"); r.From != "a" || r.To != "b:c" {
131			t.Fatalf("colon chain name rewritten: %q -> %q", r.From, r.To)
132		}
133	
134		// Force a compaction, then reopen: all four successes stay distinct and
135		// terminal, and a new id on either consumed triple still replays.
136		if err := q.store.compact(q.snapshot()); err != nil {
137			t.Fatal(err)
138		}
139		if err := q.Close(); err != nil {
140			t.Fatal(err)
141		}
142		q2, err := Open(dir)
143		if err != nil {
144			t.Fatalf("reopen compacted dir: %v", err)
145		}
146		defer q2.Close()
147		if len(q2.consumed) != 4 {
148			t.Fatalf("consumed triples lost across compaction: %v", q2.consumed)
149		}
150		for _, s := range subs[:4] {
151			if r := statusOf(t, q2, s.id); r.Status != StatusSuccess {
152				t.Fatalf("%s lost success after compaction: %s", s.id, r.Status)
153			}
154		}
155		if _, err := q2.Submit(env("c1-again", "a:b", "c", 7, 10, 0)); err != nil {
156			t.Fatal(err)
157		}
158		rep, err = q2.Advance(2000)
159		if err != nil {
160			t.Fatal(err)
161		}
162		var again Result
163		for _, r := range rep.Results {
164			if r.ID == "c1-again" {
165				again = r
166			}
167		}
168		if again.Status != StatusReplay || !strings.Contains(again.Reason, "c1") {
169			t.Fatalf("same triple under new id must replay at c1 after reopen, got %+v", again)
170		}
171	}
172	
173	// writeLegacyLog writes a V1 log exactly as older builds did, using the
174	// NUL-joined consumeKey on success entries. The first entry is the version
175	// record; callers supply the rest.
176	func writeLegacyLog(t *testing.T, dir string, entries ...*logEntry) string {
177		t.Helper()
178		path := filepath.Join(dir, logName)
179		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
180		if err != nil {
181			t.Fatal(err)
182		}
183		if _, err := f.WriteString(logMagic); err != nil {
184			t.Fatal(err)
185		}
186		if _, err := f.Write(encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))); err != nil {
187			t.Fatal(err)
188		}
189		for _, e := range entries {
190			if _, err := f.Write(encodeFrame(mustMarshal(e))); err != nil {
191				t.Fatal(err)
192			}
193		}
194		if err := f.Sync(); err != nil {
195			t.Fatal(err)
196		}
197		if err := f.Close(); err != nil {
198			t.Fatal(err)
199		}
200		return path
201	}
202	
203	// legacySuccessEntries is the realistic old-log scenario: x succeeded on
204	// "a␀b"->"c" nonce 7; r was *mis-recorded* as replay on "a"->"b␀c" nonce 7
205	// because both paths flattened to the same NUL-joined key; w is mid-backoff.
206	// The shared flattened key is: "a" NUL "b" NUL "c" NUL "7".
207	func legacyCollisionEntries() []*logEntry {
208		key := legacyNonceKey("a\x00b", "c", 7)
209		if key != legacyNonceKey("a", "b\x00c", 7) {
210			panic("test setup: legacy keys are supposed to collide")
211		}
212		return []*logEntry{
213			{T: kindSource, Chain: "a\x00b"},
214			{T: kindHeader, Chain: "a\x00b", Height: 100, Trusted: true},
215			{T: kindSubmit, Seq: 0, ID: "x", From: "a\x00b", To: "c", Nonce: 7, ProofAt: 10},
216			{T: kindResult, Now: 1000, ID: "x", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100",
217				Attempts: 1, ConsumeKey: key, ConsumeBy: "x"},
218			{T: kindSubmit, Seq: 1, ID: "r", From: "a", To: "b\x00c", Nonce: 7, ProofAt: 10},
219			{T: kindResult, Now: 1000, ID: "r", Status: StatusReplay,
220				Reason: "nonce combination already consumed by message x", Attempts: 1},
221			{T: kindSubmit, Seq: 2, ID: "w", From: "a\x00b", To: "c", Nonce: 9, ProofAt: 5000},
222			{T: kindResult, Now: 1000, ID: "w", Status: StatusWaiting,
223				Reason:   "waiting for trusted header covering height 5000 (current 100)",
224				Attempts: 1, NextRetry: 2000},
225			{T: kindAdvance, Now: 1000},
226		}
227	}
228	
229	// TestLegacyRawLogOpensDirectly covers migration of an uncompacted old log:
230	// historical success consumes only its own triple, the historical replay
231	// stays a replay (same state/reason/id, no auto-redelivery, id not reusable),
232	// the other path that merely shared the flattened key delivers under a new
233	// id, and scheduling/order/advance time are fully preserved.
234	func TestLegacyRawLogOpensDirectly(t *testing.T) {
235		dir := t.TempDir()
236		writeLegacyLog(t, dir, legacyCollisionEntries()...)
237	
238		q, err := Open(dir)
239		if err != nil {
240			t.Fatalf("old directory must open directly: %v", err)
241		}
242		defer q.Close()
243	
244		if len(q.consumed) != 1 {
245			t.Fatalf("only x's own triple may be consumed, got %v", q.consumed)
246		}
247		if winner := q.consumed[newConsumeToken("a\x00b", "c", 7)]; winner != "x" {
248			t.Fatalf("x's historical consumption lost or misattributed: %q", winner)
249		}
250		if _, taken := q.consumed[newConsumeToken("a", "b\x00c", 7)]; taken {
251			t.Fatalf("the other path must not be considered consumed after migration")
252		}
253		// The historical replay record is preserved verbatim and its id is dead.
254		if r := statusOf(t, q, "r"); r.Status != StatusReplay ||
255			!strings.Contains(r.Reason, "message x") {
256			t.Fatalf("historical replay record not preserved: %+v", r)
257		}
258		if _, err := q.Submit(env("r", "a", "b\x00c", 7, 10, 0)); !errors.Is(err, ErrTerminal) {
259			t.Fatalf("replay id must not be reusable, got %v", err)
260		}
261		// Live scheduling and processing time are restored intact.
262		if q.Now() != 1000 {
263			t.Fatalf("last advance time lost: %d", q.Now())
264		}
265		if r := statusOf(t, q, "w"); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 {
266			t.Fatalf("waiting schedule lost: %+v", r)
267		}
268		if len(q.order) != 1 || q.order[0] != "w" {
269			t.Fatalf("live order not reconstructed: %v", q.order)
270		}
271	
272		// Register the other path's source/header, then submit it with new ids:
273		// the distinct path delivers; the exact historical triple still replays
274		// attributed to the actual winner x.
275		if err := q.RegisterSource("a"); err != nil {
276			t.Fatal(err)
277		}
278		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true}); err != nil {
279			t.Fatal(err)
280		}
281		if _, err := q.Submit(env("z", "a", "b\x00c", 7, 10, 0)); err != nil {
282			t.Fatal(err)
283		}
284		if _, err := q.Submit(env("x2", "a\x00b", "c", 7, 10, 0)); err != nil {
285			t.Fatal(err)
286		}
287		rep, err := q.Advance(2000)
288		if err != nil {
289			t.Fatal(err)
290		}
291		got := map[string]Result{}
292		for _, r := range rep.Results {
293			got[r.ID] = r
294		}
295		if got["z"].Status != StatusSuccess {
296			t.Fatalf("the other path sharing the old flattened key must deliver, got %+v", got["z"])
297		}
298		if got["x2"].Status != StatusReplay || !strings.Contains(got["x2"].Reason, "x") {
299			t.Fatalf("same historical triple under new id must replay at x, got %+v", got["x2"])
300		}
301		if got["w"].Status != StatusWaiting || statusOf(t, q, "w").Attempts != 2 {
302			t.Fatalf("w should have taken one more waiting attempt: %+v", got["w"])
303		}
304		if err := q.Close(); err != nil {
305			t.Fatal(err)
306		}
307	
308		// Reopen after writing new-format records onto an old log: history must not
309		// deliver again and the new consumption relationships must hold.
310		q2, err := Open(dir)
311		if err != nil {
312			t.Fatalf("reopen mixed log: %v", err)
313		}
314		defer q2.Close()
315		if len(q2.consumed) != 2 {
316			t.Fatalf("want x and z consumed after migration, got %v", q2.consumed)
317		}
318		rep, err = q2.Advance(3000)
319		if err != nil {
320			t.Fatal(err)
321		}
322		for _, r := range rep.Results {
323			if r.Status == StatusSuccess {
324				t.Fatalf("historical success delivered again: %+v", r)
325			}
326		}
327		for _, id := range []string{"x", "z"} {
328			if r := statusOf(t, q2, id); r.Status != StatusSuccess {
329				t.Fatalf("%s must remain success after reopen: %s", id, r.Status)
330			}
331		}
332	}
333	
334	// TestLegacyCompactedLogOpensDirectly covers migration of an already
335	// compacted old directory (kindState snapshot entries with the legacy key).
336	func TestLegacyCompactedLogOpensDirectly(t *testing.T) {
337		key := legacyNonceKey("a\x00b", "c", 7)
338		entries := []*logEntry{
339			{T: kindSource, Chain: "a\x00b"},
340			{T: kindHeader, Chain: "a\x00b", Height: 100, Trusted: true},
341			{T: kindSubmit, Seq: 0, ID: "x", From: "a\x00b", To: "c", Nonce: 7, ProofAt: 10},
342			{T: kindState, Now: 1000, ID: "x", Status: StatusSuccess,
343				Reason:   "delivered; proof verified by trusted header at height 100",
344				Attempts: 1, ConsumeKey: key, ConsumeBy: "x"},
345			{T: kindSubmit, Seq: 1, ID: "r", From: "a", To: "b\x00c", Nonce: 7, ProofAt: 10},
346			{T: kindState, Now: 1000, ID: "r", Status: StatusReplay,
347				Reason: "nonce combination already consumed by message x", Attempts: 1},
348			{T: kindAdvance, Now: 1000},
349		}
350		dir := t.TempDir()
351		writeLegacyLog(t, dir, entries...)
352	
353		q, err := Open(dir)
354		if err != nil {
355			t.Fatalf("old compacted directory must open directly: %v", err)
356		}
357		defer q.Close()
358		if winner := q.consumed[newConsumeToken("a\x00b", "c", 7)]; winner != "x" {
359			t.Fatalf("x consumption not restored from old snapshot: %v", q.consumed)
360		}
361		if _, taken := q.consumed[newConsumeToken("a", "b\x00c", 7)]; taken {
362			t.Fatalf("other path must not be consumed by old snapshot")
363		}
364		if r := statusOf(t, q, "r"); r.Status != StatusReplay ||
365			!strings.Contains(r.Reason, "message x") {
366			t.Fatalf("historical replay snapshot not preserved: %+v", r)
367		}
368		if r := statusOf(t, q, "x"); r.Status != StatusSuccess {
369			t.Fatalf("historical success snapshot changed: %s", r.Status)
370		}
371	
372		// Continuing writes on an old compacted log, then compacting again, must
373		// keep everything consistent across yet another reopen.
374		if err := q.RegisterSource("a"); err != nil {
375			t.Fatal(err)
376		}
377		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true}); err != nil {
378			t.Fatal(err)
379		}
380		if _, err := q.Submit(env("z", "a", "b\x00c", 7, 10, 0)); err != nil {
381			t.Fatal(err)
382		}
383		if _, err := q.Advance(2000); err != nil {
384			t.Fatal(err)
385		}
386		if err := q.store.compact(q.snapshot()); err != nil {
387			t.Fatal(err)
388		}
389		if err := q.Close(); err != nil {
390			t.Fatal(err)
391		}
392		q2, err := Open(dir)
393		if err != nil {
394			t.Fatalf("reopen recompacted log: %v", err)
395		}
396		defer q2.Close()
397		if r := statusOf(t, q2, "z"); r.Status != StatusSuccess {
398			t.Fatalf("z lost after recompaction: %s", r.Status)
399		}
400		if len(q2.consumed) != 2 {
401			t.Fatalf("consumed triples wrong after recompaction: %v", q2.consumed)
402		}
403	}
404	
405	// TestLegacyInconsistentSuccessRejected verifies that an old success record
406	// whose consume key does not match its own message content is rejected as
407	// corrupt — for both raw result entries and compacted state entries — with
408	// the on-disk bytes left untouched.
409	func TestLegacyInconsistentSuccessRejected(t *testing.T) {
410		cases := map[string][]*logEntry{
411			"raw result": {
412				{T: kindSource, Chain: "a"},
413				{T: kindSubmit, Seq: 0, ID: "x", From: "a", To: "b", Nonce: 1, ProofAt: 10},
414				// Key claims a different nonce than the message itself.
415				{T: kindResult, Now: 1000, ID: "x", Status: StatusSuccess, Attempts: 1,
416					ConsumeKey: legacyNonceKey("a", "b", 2), ConsumeBy: "x"},
417			},
418			"raw result wrong by": {
419				{T: kindSource, Chain: "a"},
420				{T: kindSubmit, Seq: 0, ID: "x", From: "a", To: "b", Nonce: 1, ProofAt: 10},
421				{T: kindResult, Now: 1000, ID: "x", Status: StatusSuccess, Attempts: 1,
422					ConsumeKey: legacyNonceKey("a", "b", 1), ConsumeBy: "y"},
423			},
424			"compacted state": {
425				{T: kindSource, Chain: "a"},
426				{T: kindSubmit, Seq: 0, ID: "x", From: "a", To: "b", Nonce: 1, ProofAt: 10},
427				{T: kindState, Now: 1000, ID: "x", Status: StatusSuccess, Attempts: 1,
428					ConsumeKey: legacyNonceKey("a", "c", 1), ConsumeBy: "x"},
429			},
430			"new triple mismatch": {
431				{T: kindSource, Chain: "a"},
432				{T: kindSubmit, Seq: 0, ID: "x", From: "a", To: "b", Nonce: 1, ProofAt: 10},
433				{T: kindResult, Now: 1000, ID: "x", Status: StatusSuccess, Attempts: 1,
434					ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 9, ConsumeBy: "x"},
435			},
436		}
437		for name, entries := range cases {
438			t.Run(name, func(t *testing.T) {
439				dir := t.TempDir()
440				path := writeLegacyLog(t, dir, entries...)
441				before, err := os.ReadFile(path)
442				if err != nil {
443					t.Fatal(err)
444				}
445				q, err := Open(dir)
446				if !errors.Is(err, ErrCorrupt) {
447					if q != nil {
448						q.Close()
449					}
450					t.Fatalf("want ErrCorrupt, got %v", err)
451				}
452				after, err := os.ReadFile(path)
453				if err != nil {
454					t.Fatal(err)
455				}
456				if string(after) != string(before) {
457					t.Fatalf("inconsistent directory must be preserved byte-for-byte")
458				}
459			})
460		}
461	}
462	
463	// TestConcurrentDistinctPathsNoCrossInterference: two distinct triples under
464	// concurrent submission (including the colon-ambiguous names) must yield
465	// exactly one success each, while every same-triple contender is a replay.
466	func TestConcurrentDistinctPathsNoCrossInterference(t *testing.T) {
467		q, _ := openTempQueue(t)
468		defer q.Close()
469		for _, chain := range []string{"a", "a:b"} {
470			if err := q.RegisterSource(chain); err != nil {
471				t.Fatal(err)
472			}
473			if err := q.UpsertHeader(Header{Chain: chain, Height: 100, Trusted: true}); err != nil {
474				t.Fatal(err)
475			}
476		}
477	
478		const perPath = 20
479		var wg sync.WaitGroup
480		for i := 0; i < perPath; i++ {
481			wg.Add(2)
482			go func(i int) {
483				defer wg.Done()
484				_, _ = q.Submit(env(fmt.Sprintf("p1-%02d", i), "a", "b", 1, 10, 0))
485			}(i)
486			go func(i int) {
487				defer wg.Done()
488				_, _ = q.Submit(env(fmt.Sprintf("p2-%02d", i), "a:b", "c", 1, 10, 0))
489			}(i)
490		}
491		wg.Wait()
492		rep, err := q.Advance(1000)
493		if err != nil {
494			t.Fatal(err)
495		}
496		success := map[string]int{}
497		replays := 0
498		for _, r := range rep.Results {
499			switch r.Status {
500			case StatusSuccess:
501				success[q.records[r.ID].Msg.Message.From]++
502			case StatusReplay:
503				replays++
504			default:
505				t.Fatalf("unexpected status for %s: %s", r.ID, r.Status)
506			}
507		}
508		if len(success) != 2 || success["a"] != 1 || success["a:b"] != 1 {
509			t.Fatalf("want exactly one success per distinct path, got %v", success)
510		}
511		if replays != 2*perPath-2 {
512			t.Fatalf("want %d replays, got %d", 2*perPath-2, replays)
513		}
514		if len(q.consumed) != 2 {
515			t.Fatalf("consumed triples: %v", q.consumed)
516		}
517	}
