// fields (attempt count, processing time, status, reason, retry time) are
// applied once here; a success additionally records the nonce consumption and
// both kinds of settled results leave the live processing order.
func (q *Queue) commitOutcome(rec *Record, o outcome) error {
	if err := q.store.appendOutcome(rec, o); err != nil {
		return q.fail(o.failOp(), err)
	}
	rec.Attempts = o.attempts
	rec.LastProcAt = o.now
	rec.Status = o.status
	rec.Reason = o.reason
	rec.NextRetry = o.nextRetry
	switch o.status {
	case StatusSuccess:
		q.consumed[o.consumeToken] = o.consumeBy
		q.removeFromOrder(o.consumeBy)
	case StatusWaiting:
		// stays live and processable, keeps its place in the processing order
	default:
		q.removeFromOrder(rec.Msg.Message.ID)
	}
