// failOp names the storage operation in the ErrStorage message. The labels
// match the historical per-path wording.
func (o outcome) failOp() string {
	switch o.status {
	case StatusWaiting:
		return "schedule retry"
	case StatusSuccess:
		return "deliver"
	default:
		return "terminalize"
	}
